style.css:
/* Bubblegum Dream — Google */

/* swap these colors to customize the pink */
:root {
  --my-bg: #fff0f6;
  --my-surface: #ffe0ed;
  --my-pink: #ffb6d2;
  --my-dark-pink: #c2185b;
  --my-text: #a31550;
  --my-border: #f4a6c7;
}

/* page backgrounds */
html,
body {
  background: var(--my-bg) !important;
  color: var(--my-text) !important;
}

/* text and headings */
h1, h2, h3, h4, p, span, label {
  color: var(--my-text) !important;
}

/* links */
a {
  color: var(--my-dark-pink) !important;
}

/* search boxes */
input,
textarea,
[role="combobox"] {
  background: var(--my-surface) !important;
  color: var(--my-dark-pink) !important;
  border-color: var(--my-border) !important;
  border-radius: 24px !important;
}

/* buttons */
button {
  background: var(--my-pink) !important;
  color: var(--my-dark-pink) !important;
  border-color: var(--my-border) !important;
  border-radius: 20px !important;
}

/* cards and panels */
[role="dialog"],
[role="menu"],
[role="listbox"] {
  background: var(--my-surface) !important;
  border-color: var(--my-border) !important;
}

/* images */
img {
  border-radius: 10px !important;
}
